CREATE DATABASE IF NOT EXISTS bus_booking; USE bus_booking;
DROP TABLE IF EXISTS bookings; DROP TABLE IF EXISTS buses; DROP TABLE IF EXISTS users;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('user','admin') DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE buses(id INT AUTO_INCREMENT PRIMARY KEY,bus_name VARCHAR(100) NOT NULL,bus_number VARCHAR(30) UNIQUE NOT NULL,bus_type VARCHAR(50) NOT NULL,source VARCHAR(100) NOT NULL,destination VARCHAR(100) NOT NULL,departure_time TIME NOT NULL,arrival_time TIME NOT NULL,journey_date DATE NOT NULL,fare DECIMAL(10,2) NOT NULL,total_seats INT DEFAULT 40,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE bookings(id INT AUTO_INCREMENT PRIMARY KEY,booking_id VARCHAR(30) UNIQUE NOT NULL,user_id INT NOT NULL,bus_id INT NOT NULL,passenger_name VARCHAR(100) NOT NULL,passenger_age INT NOT NULL,passenger_gender VARCHAR(20) NOT NULL,passenger_phone VARCHAR(20) NOT NULL,seats VARCHAR(255) NOT NULL,total_amount DECIMAL(10,2) NOT NULL,status ENUM('Confirmed','Cancelled') DEFAULT 'Confirmed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(bus_id) REFERENCES buses(id) ON DELETE CASCADE);
